/// Looks up an operation code, or `None` when the number is not assigned.
///
/// An unassigned number is refused rather than ignored, so a program built
/// against a later table fails visibly instead of silently succeeding.
#[must_use]
pub fn spec(code: u32) -> Option<&'static OpSpec> {
    let mut index = 0;
    while index < OPERATIONS.len() {
        if OPERATIONS[index].code == code {
            return Some(&OPERATIONS[index]);
        }
        index += 1;
    }
    None
}

/// Status values returned in RAX. Zero is success, every error is negative.
pub mod status {
    /// Operation completed.
    pub const OK: i64 = 0;
    /// The entry identifier is not implemented by this revision.
    pub const UNSUPPORTED_ENTRY: i64 = -1;
    /// Structurally rejected before any effect.
    pub const INVALID_ARGUMENT: i64 = -2;
    /// Descriptor major version not supported. Rejected before effects.
    pub const INCOMPATIBLE_VERSION: i64 = -3;
    /// No live entry names that index and generation.
    pub const INVALID_HANDLE: i64 = -4;
    /// The operation does not belong to the object's type.
    pub const WRONG_TYPE: i64 = -5;
    /// The grant does not carry every right the operation requires.
    pub const INSUFFICIENT_RIGHTS: i64 = -6;
    /// A monotonic deadline in the lineage has passed.
    pub const EXPIRED: i64 = -7;
    /// A scope or grant in the lineage is fenced.
    pub const SCOPE_CLOSED: i64 = -8;
    /// A reservation did not fit in every ancestor.
    pub const LIMIT_EXHAUSTED: i64 = -9;
    /// The bounded queue has no room and no slot is reserved for this traffic.
    pub const QUEUE_FULL: i64 = -10;
    /// A user address is unmapped or lacks the required rights.
    pub const INVALID_ADDRESS: i64 = -11;
    /// The other end of the operation no longer exists.
    pub const PEER_DEAD: i64 = -12;
    /// The wait ended because its authority was closed.
    pub const CANCELLED: i64 = -13;
    /// The obligation is admitted and not yet resolved.
    pub const PENDING: i64 = -14;
    /// The operation would have waited and no deadline allowed it.
    pub const WOULD_BLOCK: i64 = -15;
    /// The deadline passed before the wait completed. Not a proof of absence of effect.
    pub const TIMED_OUT: i64 = -16;
    /// A one-shot object was already consumed.
    pub const ALREADY_RESOLVED: i64 = -17;
    /// The object's state forbids the operation.
    pub const STATE_CONFLICT: i64 = -18;
    /// Obligations remain inside the closing perimeter.
    pub const DRAIN_INCOMPLETE: i64 = -19;
    /// The operation exists but this revision does not implement it.
    pub const NOT_SUPPORTED: i64 = -20;
    /// The isolation profile the caller required is not the one this machine can satisfy. Refused before any effect, never downgraded silently.
    pub const UNSUPPORTED_PROFILE: i64 = -21;
}

